using XCL2.App.Models;
using XCL2.App.Services;

int checks = 0;
void Check(bool condition, string name) { ++checks; if (!condition) throw new Exception(name); }
var config = new AppConfig();
Check(!config.Ux50SearchHistory && !config.Ux50SearchSavedFilters, "History and presets remain opt-in");
ExperienceSearchState.Remember(config, "mods", "sodium");
ExperienceSearchState.SavePreset(config, "mods", "test", new() { ["query"] = "sodium" });
Check(config.Ux50SearchHistoryItems.Count == 0 && config.Ux50SearchFilterPresets.Count == 0, "Disabled features do not persist");
Check(ExperienceSearchState.Matches("Ｆａｂｒｉｃ 1.21 Sodium", "fabric　sodium"), "Unicode/case normalization and all words");
Check(!ExperienceSearchState.Matches("Fabric 1.21 Sodium", "fabric forge"), "Every keyword must match");
Check(!ExperienceSearchState.Matches("Fabric 1.21 Sodium", "fabric sodium", false), "Single phrase mode preserves contiguous semantics");
Check(ExperienceSearchState.Matches("anything", " \t"), "Empty local query keeps all items");
config.Ux50SearchHistory = true;
for (int index = 0; index < 30; ++index) ExperienceSearchState.Remember(config, "mods", "query" + index);
Check(config.Ux50SearchHistoryItems.Count == ExperienceSearchState.HistoryLimit, "History retention is bounded");
ExperienceSearchState.Remember(config, "mods", "QUERY29");
Check(config.Ux50SearchHistoryItems.Count == 20 && config.Ux50SearchHistoryItems[0].Query == "QUERY29", "Repeated query moves to top without duplicates");
ExperienceSearchState.Remember(config, "versions", "QUERY29");
Check(config.Ux50SearchHistoryItems.Count(item => item.Query == "QUERY29") == 2, "History scopes stay independent");
config.Ux50SearchHistory = false;
var historyBefore = config.Ux50SearchHistoryItems.Select(item => item.Query).ToArray();
ExperienceSearchState.Remember(config, "mods", "should not record");
Check(historyBefore.SequenceEqual(config.Ux50SearchHistoryItems.Select(item => item.Query)), "Disabling history keeps old entries but adds nothing");
config.Ux50SearchSavedFilters = true;
var filter = new Dictionary<string, string> { ["query"] = "sodium", ["loader"] = "fabric" };
ExperienceSearchState.SavePreset(config, "mods", "Sodium / Fabric", filter);
filter["loader"] = "forge";
Check(config.Ux50SearchFilterPresets[0].Values["loader"] == "fabric", "Saved filter owns a detached snapshot");
ExperienceSearchState.SavePreset(config, "mods", "same values", new() { ["loader"] = "fabric", ["query"] = "sodium" });
Check(config.Ux50SearchFilterPresets.Count == 1, "Identical filters deduplicate regardless of dictionary order");
for (int index = 0; index < 20; ++index) ExperienceSearchState.SavePreset(config, "mods", "preset" + index, new() { ["query"] = index.ToString() });
Check(config.Ux50SearchFilterPresets.Count == ExperienceSearchState.PresetLimit, "Preset retention bounded");
var ranges = ExperienceSearchState.HighlightRanges("Sodium sodium + Fabric", "sodium sodium sod fabric");
Check(ranges.Count == 3 && ranges[0] == (0, 6) && ranges[1] == (7, 6) && ranges[2] == (16, 6), "Overlapping highlight words merge without duplicate text");
Check(ExperienceSearchState.HighlightRanges("中文 ＡＢ", "中文").Single() == (0, 2), "Ranges preserve original string offsets");
Check(ExperienceSearchState.HighlightRanges("中文 ＡＢ", "ab").Single() == (3, 2), "Width-normalized matching highlights original characters");
Check(ExperienceSearchState.HighlightRanges("ﬁle", "file").Single() == (0, 3), "Expanded ligature normalization does not shift original indices");
var sortRows = new[] { (Name: "one", Key: 3), (Name: "two", Key: 1), (Name: "three", Key: 3), (Name: "four", Key: 1) };
Check(ExperienceSearchState.StableOrder(sortRows, row => row.Key, false).Select(row => row.Name).SequenceEqual(new[] { "two", "four", "one", "three" }), "Ascending ties preserve source order");
Check(ExperienceSearchState.StableOrder(sortRows, row => row.Key, true).Select(row => row.Name).SequenceEqual(new[] { "one", "three", "two", "four" }), "Descending does not reverse tied rows");
string summary = ExperienceSearchState.LoadedSummary(1, 31, 100, 500, 20);
Check(summary.Contains("31") && summary.Contains("第 2 页") && !summary.Contains("600"), "Combined sources count actual loaded items rather than adding overlapping totals");

config.Ux50SearchFilterPresets = new() { null!, new() { Scope = "features", Label = null!, Values = null! } };
config.Ux50SearchHistoryItems = new() { null!, new() { Scope = "features", Query = null! }, new() { Scope = "mods", Query = "safe" } };
ExperienceSearchState.Normalize(config);
Check(config.Ux50SearchFilterPresets.Count == 1 && config.Ux50SearchFilterPresets[0].Values.Count == 0, "imported null rows and preset dictionaries normalize safely");
Check(config.Ux50SearchHistoryItems.Count == 1 && config.Ux50SearchHistoryItems[0].Query == "safe", "invalid history rows removed without losing valid data");
ExperienceSearchState.SavePreset(config, "features", null!, new() { ["query"] = null! });
Check(config.Ux50SearchFilterPresets.All(row => row.Values != null && row.Values.Values.All(value => value != null)), "saving over imported state has no nested null dereference");
var canceledFirst = ExperienceSearchState.RecoverCanceledPage(null, 20);
Check(canceledFirst.Index == 0 && !canceledFirst.PreviousEnabled && !canceledFirst.NextEnabled && canceledFirst.Caption.Contains("已取消"), "first canceled request is actionable rather than stuck loading");
var canceledNext = ExperienceSearchState.RecoverCanceledPage(new(2, 20, 100, 0), 20);
Check(canceledNext.Index == 2 && canceledNext.PreviousEnabled && canceledNext.NextEnabled && canceledNext.Caption.Contains("第 3 页"), "canceled navigation restores displayed page and its actual controls");
var canceledLast = ExperienceSearchState.RecoverCanceledPage(new(4, 7, 87, 0), 20);
Check(canceledLast.PreviousEnabled && !canceledLast.NextEnabled, "canceled request cannot invent a next page");
Console.WriteLine($"Experience search regression: {checks} checks passed.");
